namespace ghidra.app.plugin.core.equate;



using ghidra.app.cmd.equate;
using ghidra.app.context;
using ghidra.framework.cmd;
using ghidra.program.database.symbol;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.scalar;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.util.task;

/**
 * Class to handle creating new equates for a selection or the whole program
 */
public class CreateEquateCmd : BackgroundCommand<Program> {

	private CodeUnitIterator iterator; //iterator over selected instructions or null if no selection
	private string equateName; // user defined equate name
	private bool overwriteExisting; //user defined overwrite option
	private long targetScalarValue;
	private ListingActionContext context;
	private Enum enoom;

	/**
	 * 
	 * @param scalar user defined scalar to search for in program
	 * @param iter the range of code units for which to maybe create equates
	 * @param equateName user defined name for the new equate to be set
	 * @param overwriteExisting true to rename existing equates
	 * @param context the action context
	 */
	public CreateEquateCmd(Scalar scalar, CodeUnitIterator iter, string equateName,
			bool overwriteExisting, ListingActionContext context) : base("Create New Equate", true /* has progress */, true /* can cancel */,
			false /* is modal */)
    {
		this.targetScalarValue = scalar.getValue();
		this._iterator = iter;
		this.equateName = Objects.requireNonNull(equateName);
		this.overwriteExisting = overwriteExisting;
		this.context = context;
	}

	/**
	 * 
	 * @param scalar user defined scalar to search for in program
	 * @param iter the range of code units for which to maybe create equates
	 * @param enoom the enum to use for formatting the equate name
	 * @param overwriteExisting true to rename existing equates
	 * @param context the action context
	 */
	public CreateEquateCmd(Scalar scalar, CodeUnitIterator iter, Enum enoom,
			bool overwriteExisting, ListingActionContext context) : base("Create New Equate", true /* has progress */, true /* can cancel */,
			false /* is modal */)
    {
		this.targetScalarValue = scalar.getValue();
		this._iterator = iter;
		this.overwriteExisting = overwriteExisting;
		this.context = context;
		this.enoom = Objects.requireNonNull(enoom);
	}

	/* @Override */
	public bool applyTo(Program program, TaskMonitor monitor) {

		monitor.setIndeterminate(true);
		monitor.setMessage("Creating Equate");

		while (_iterator.hasNext() && !monitor.isCancelled()) {
			CodeUnit cu = _iterator.next();
			if (cu is Instruction) {
				maybeCreateEquate(program, (Instruction) cu);
			}
			else if (cu is Data) {
				maybeCreateEquate(program, (Data) cu);
			}
		}
		return true;
	}

	private void maybeCreateEquate(Program program, Data data) {

		if (!data.isDefined()) {
			return;
		}

		object val = data.getValue();
		if (!(val is Scalar)) {
			return;
		}

		Scalar scalar = (Scalar) val;
		if (scalar.getValue() != targetScalarValue) {
			return;
		}

		int opIndex = getOperandIndex();
		createEquate(program, data, opIndex, scalar);
	}

	private void maybeCreateEquate(Program program, Instruction instruction) {
		for (int opIndex = 0; opIndex < instruction.getNumOperands(); opIndex++) {
			object[] opObjects = instruction.getOpObjects(opIndex);
			foreach (object opObject in opObjects) {
				if (!(opObject is Scalar)) {
					continue;
				}

				Scalar scalar = (Scalar) opObject;
				if (scalar.getValue() != targetScalarValue) {
					continue;
				}

				createEquate(program, instruction, opIndex, scalar);
			}
		}
	}

	private void createEquate(Program program, CodeUnit codeUnit, int opIndex, Scalar scalar) {

		EquateTable equateTable = codeUnit.getProgram().getEquateTable();
		Address address = codeUnit.getAddress();
		Equate curEquate = equateTable.getEquate(address, opIndex, targetScalarValue);

		if (equateName == null && enoom != null) {
			this.equateName = generateFormattedEquateName();
		}

		if (curEquate == null) {
			SetEquateCmd cmd = new SetEquateCmd(equateName, address, opIndex, targetScalarValue);
			cmd.applyTo(program);
		}
		else if (overwriteExisting) {
			RenameEquateCmd cmd =
				new RenameEquateCmd(curEquate.getName(), equateName, address, opIndex);
			cmd.applyTo(program);
		}
	}

	private string generateFormattedEquateName() {
		Program program = context.getProgram();
		Enum enumWithId = (Enum) program.getDataTypeManager().addDataType(enoom, null);
		string formattedName =
			EquateManager.formatNameForEquate(enumWithId.getUniversalID(), targetScalarValue);
		return formattedName;
	}

	/**
	 * Get the operand index at the location
	 *
	 * @return 0-3 for a good operand location, -1 otherwise
	 */
	private int getOperandIndex() {
		ProgramLocation location = context.getLocation();
		if (location is OperandFieldLocation) {
			return ((OperandFieldLocation) location).getOperandIndex();
		}
		return -1;
	}
}
